// Datos inventados: tarifa por kilo según la zona, y un recargo del 10 % para el interior.
const TARIFAS = { caba: 800, gba: 1100, interior: 1500 };

// ANTES: la pantalla y el reporte del mes llevan cada uno su propia copia de la regla.
function pantallaCotizarAntes(zona, kg) {
  let precio = TARIFAS[zona] * kg;
  if (zona === 'interior') precio *= 1.10; // recargo, agregado el lunes
  return Math.round(precio);
}
function reporteMensualAntes(envios) {
  let total = 0;
  for (const e of envios) total += TARIFAS[e.zona] * e.kg; // nadie se acordó de este lugar
  return Math.round(total);
}
const envios = [{ zona: 'interior', kg: 4 }, { zona: 'caba', kg: 2 }];
console.log('ANTES   pantalla (interior, 4 kg): $' + pantallaCotizarAntes('interior', 4));
console.log('ANTES   reporte de los 2 envíos:   $' + reporteMensualAntes(envios), '(debería ser $8200)');

// DESPUÉS: cuatro capas. Cada una solo conoce a la de abajo.
const datos = { tarifaPorKg: (zona) => TARIFAS[zona] };                       // DATOS
const crearDominio = (repo) => ({                                              // DOMINIO: la regla, una sola vez
  precioEnvio({ zona, kg }) {
    const base = repo.tarifaPorKg(zona) * kg;
    return Math.round(zona === 'interior' ? base * 1.10 : base);
  },
});
const crearAplicacion = (dominio) => ({                                        // APLICACIÓN: casos de uso
  cotizar: (envio) => dominio.precioEnvio(envio),
  facturado: (lista) => lista.reduce((suma, e) => suma + dominio.precioEnvio(e), 0),
});
const app = crearAplicacion(crearDominio(datos));
const pantalla = (envio) => `Total: $${app.cotizar(envio)}`;                   // PRESENTACIÓN: solo formatea
const reporte = (lista) => `Facturado: $${app.facturado(lista)}`;

console.log('DESPUÉS ' + pantalla(envios[0]));
console.log('DESPUÉS ' + reporte(envios));

// La regla se prueba sola, con un repositorio falso: sin pantalla y sin base de datos.
const falso = crearDominio({ tarifaPorKg: () => 1000 });
console.log('prueba del dominio:', falso.precioEnvio({ zona: 'interior', kg: 1 }) === 1100 ? 'ok' : 'FALLA');

// MVC «de escritorio»: el modelo avisa y las vistas se redibujan solas.
class Despacho {
  #estado = 'armado';
  #oyentes = [];
  suscribir(fn) { this.#oyentes.push(fn); }
  get estado() { return this.#estado; }
  salir() {
    if (this.#estado !== 'armado') throw new Error('solo sale un despacho armado');
    this.#estado = 'en_ruta';
    this.#oyentes.forEach((fn) => fn(this)); // observador, como en el día anterior
  }
}
const vistaTabla = (m) => console.log(`[tabla] D-7 -> ${m.estado}`);
const vistaMapa = (m) => console.log(`[mapa]  camioneta ${m.estado === 'en_ruta' ? 'en movimiento' : 'quieta'}`);

// El controlador traduce un gesto en una orden al modelo. No dibuja nada.
const crearControlador = (modelo) => ({
  alApretarSalir() {
    try { modelo.salir(); } catch (e) { console.log('[aviso] ' + e.message); }
  },
});

const d = new Despacho();
d.suscribir(vistaTabla);
d.suscribir(vistaMapa);
const controlador = crearControlador(d);
controlador.alApretarSalir(); // el modelo cambia y las dos vistas se enteran
controlador.alApretarSalir(); // el modelo se defiende de una orden ilegal

