const modeloWeb = { buscar: (id) => ({ id, estado: 'en_ruta' }) };
const vistaWeb = (despacho) => `<p>Despacho ${despacho.id}: ${despacho.estado}</p>`;
const controladorWeb = (pedido) => vistaWeb(modeloWeb.buscar(pedido.id));
console.log(controladorWeb({ id: 'D-7' }));

import os, re, sys
from collections import Counter

RAIZ = sys.argv[1]                                  # carpeta src/ de la app (solo lectura)
CAPAS = ['util', 'datos', 'estado', 'componentes', 'pantallas']   # de abajo hacia arriba (orden elegido a partir del mapa)
IMPORT = re.compile(r"""(?:from|import)\s*\(?\s*['"](\.[^'"]+)['"]""")

def capa(ruta):
    p = os.path.relpath(ruta, RAIZ).split(os.sep)
    return p[0] if len(p) > 1 and p[0] in CAPAS else None

aristas = set()                                     # pares únicos archivo -> archivo
for d, _, fs in os.walk(RAIZ):
    for f in fs:
        if not f.endswith(('.ts', '.tsx', '.js')) or f.endswith('.d.ts'):
            continue
        ruta = os.path.join(d, f)
        for imp in IMPORT.findall(open(ruta, encoding='utf8').read()):
            dest = os.path.normpath(os.path.join(d, imp))
            if capa(ruta) and capa(dest) and capa(ruta) != capa(dest):
                aristas.add((os.path.relpath(ruta, RAIZ), os.path.relpath(dest, RAIZ)))

abajo = Counter(); arriba = Counter(); saltos = 0
for a, b in aristas:
    ia, ib = CAPAS.index(capa(RAIZ + '/' + a)), CAPAS.index(capa(RAIZ + '/' + b))
    if ia > ib:
        abajo[(capa(RAIZ + '/' + a), capa(RAIZ + '/' + b))] += 1
        saltos += ia - ib > 1
    else:
        arriba[(capa(RAIZ + '/' + a), capa(RAIZ + '/' + b))] += 1

print(f'{len(aristas)} dependencias archivo->archivo entre las 5 capas')
print(f'hacia abajo: {sum(abajo.values())}  (de ellas, saltando alguna capa: {saltos})')
print(f'hacia arriba: {sum(arriba.values())}')
for (a, b), n in sorted(arriba.items(), key=lambda x: -x[1]):
    print(f'   {a} -> {b}: {n}')
